const metaAccessToken = $env.META_ACCESS_TOKEN || 'EAAG_DENTALPIN_META_ACCESS_TOKEN';
const metaAppId = $env.META_APP_ID || '123456789012345';
const metaAppSecret = $env.META_APP_SECRET || 'abcdef0123456789abcdef0123456789';
const alertWebhookUrl = $env.ALERT_WEBHOOK_URL || ($env.DENTALPIN_API_BASE_URL || 'https://dental-api-2z19.onrender.com') + '/api/v1/notifications';

return [
  {
    json: {
      meta_access_token: metaAccessToken,
      meta_app_id: metaAppId,
      meta_app_secret: metaAppSecret,
      alert_webhook_url: alertWebhookUrl,
      check_timestamp: $now.toISO()
    }
  }
];

const init = $('Init Token Parameters').first().json;
const debugResponse = $json || {};
const tokenData = debugResponse.data || {};

const isValid = tokenData.is_valid === true;
const expiresAt = typeof tokenData.expires_at === 'number' ? tokenData.expires_at : 0;
const dataAccessExpiresAt = typeof tokenData.data_access_expires_at === 'number' ? tokenData.data_access_expires_at : 0;
const scopes = Array.isArray(tokenData.scopes) ? tokenData.scopes : [];
const appId = tokenData.app_id || init.meta_app_id;
const userId = tokenData.user_id || '';
const tokenType = tokenData.type || 'UNKNOWN';

const nowSec = Math.floor(Date.now() / 1000);

let daysRemaining = 9999;
let isPermanent = false;
let expiryDateFormatted = 'Illimité (Jeton de Page Permanent)';

if (expiresAt === 0) {
  isPermanent = true;
} else {
  daysRemaining = Math.max(0, Math.round((expiresAt - nowSec) / 86400));
  const expDate = new Date(expiresAt * 1000);
  expiryDateFormatted = expDate.toISOString().replace('T', ' ').substring(0, 19) + ' UTC';
}

// Determine state
let status = 'HEALTHY';
let needsRefresh = false;
let isCritical = false;

if (!isValid) {
  status = 'INVALID_OR_REVOKED';
  isCritical = true;
} else if (isPermanent) {
  status = 'PERMANENT_HEALTHY';
  needsRefresh = false;
} else if (daysRemaining <= 7) {
  status = 'EXPIRING_SOON';
  needsRefresh = true;
  if (daysRemaining <= 3) {
    isCritical = true;
  }
} else {
  status = 'HEALTHY';
}

return [
  {
    json: {
      status: status,
      is_valid: isValid,
      is_permanent: isPermanent,
      needs_refresh: needsRefresh,
      is_critical: isCritical,
      days_remaining: daysRemaining,
      expiry_date: expiryDateFormatted,
      token_type: tokenType,
      scopes: scopes,
      app_id: appId,
      user_id: userId,
      meta_access_token: init.meta_access_token,
      meta_app_id: init.meta_app_id,
      meta_app_secret: init.meta_app_secret,
      alert_webhook_url: init.alert_webhook_url,
      checked_at: $now.toISO()
    }
  }
];

const tokenInfo = $('Analyze Token Health & Expiration').first().json;
const exchangeRes = $json || {};

const newAccessToken = exchangeRes.access_token;
const expiresIn = exchangeRes.expires_in || 5184000;
const newDays = Math.round(expiresIn / 86400);
const refreshSuccess = !!newAccessToken;

return [
  {
    json: {
      refresh_success: refreshSuccess,
      is_critical: !refreshSuccess,
      status: refreshSuccess ? 'TOKEN_REFRESHED' : 'REFRESH_FAILED',
      old_status: tokenInfo.status,
      days_remaining: refreshSuccess ? newDays : tokenInfo.days_remaining,
      expiry_date: refreshSuccess ? `~${$now.plus({ days: newDays }).toFormat('yyyy-MM-dd')}` : tokenInfo.expiry_date,
      new_access_token: newAccessToken || 'REFRESH_FAILED',
      token_type: exchangeRes.token_type || 'bearer',
      app_id: tokenInfo.app_id,
      scopes: tokenInfo.scopes,
      alert_webhook_url: tokenInfo.alert_webhook_url,
      exchange_error: exchangeRes.error ? exchangeRes.error.message : null,
      message: refreshSuccess
        ? `Jeton d'accès Meta renouvelé avec succès pour ${newDays} jours.`
        : `Échec du renouvellement automatique Meta : ${exchangeRes.error?.message || 'Erreur inconnue'}`
    }
  }
];

const result = $json;

return [
  {
    json: {
      success: true,
      event: 'TOKEN_REFRESHED',
      status: 'HEALTHY',
      days_remaining: result.days_remaining,
      expiry_date: result.expiry_date,
      message: result.message,
      refreshed_at: $now.toISO()
    }
  }
];

const tokenInfo = $('Analyze Token Health & Expiration').first().json;
const refreshEval = $('Evaluate Refresh Result').first()?.json || {};

const isRefreshFailure = refreshEval.refresh_success === false;
const statusLabel = isRefreshFailure ? 'ÉCHEC RENOUVELLEMENT' : (tokenInfo.status || 'CRITIQUE');

const alertPayload = {
  severity: 'CRITICAL',
  service: 'DentalPin Social Automation',
  title: 'ALERTE META TOKEN : Action Requise Immédiate',
  message: isRefreshFailure
    ? `Le renouvellement automatique du jeton Meta pour Dr. Mokhtar / DentalPin a échoué (${refreshEval.exchange_error || 'Erreur API'}). Expiration: ${tokenInfo.expiry_date} (${tokenInfo.days_remaining} jours restants).`
    : `Le jeton d'accès Meta pour Dr. Mokhtar / DentalPin nécessite une attention immédiate. Statut: ${tokenInfo.status}. Jours restants: ${tokenInfo.days_remaining}. Date d'expiration: ${tokenInfo.expiry_date}.`,
  action_required: 'Générez un nouveau jeton dans Meta Graph API Explorer et mettez à jour la variable META_ACCESS_TOKEN dans n8n.',
  details: {
    status: statusLabel,
    days_remaining: tokenInfo.days_remaining,
    expiry_date: tokenInfo.expiry_date,
    app_id: tokenInfo.app_id,
    scopes: tokenInfo.scopes,
    error: isRefreshFailure ? refreshEval.exchange_error : null
  },
  alert_webhook_url: tokenInfo.alert_webhook_url,
  timestamp: $now.toISO()
};

return [
  {
    json: alertPayload
  }
];

const alertData = $('Prepare Critical Token Alert').first().json;
const dispatchResponse = $json;

return [
  {
    json: {
      alert_dispatched: true,
      title: alertData.title,
      severity: alertData.severity,
      message: alertData.message,
      target_url: alertData.alert_webhook_url,
      dispatch_response: dispatchResponse,
      dispatched_at: $now.toISO()
    }
  }
];

const tokenInfo = $('Analyze Token Health & Expiration').first().json;

return [
  {
    json: {
      status: 'AUDIT_PASSED',
      health: 'HEALTHY',
      token_status: tokenInfo.status,
      is_permanent: tokenInfo.is_permanent,
      days_remaining: tokenInfo.days_remaining,
      expiry_date: tokenInfo.expiry_date,
      scopes: tokenInfo.scopes,
      message: `Meta Token est en bonne santé. Expire le: ${tokenInfo.expiry_date} (${tokenInfo.days_remaining} jours restants).`
    }
  }
];
